
import React, { useState, useEffect } from 'react';
import { X, ChevronRight, Sparkles, Plus, Edit2, Settings, MousePointer2, BookOpen, ShieldCheck, CheckCircle2 } from 'lucide-react';

interface TutorialOverlayProps {
  onClose: () => void;
}

const TutorialOverlay: React.FC<TutorialOverlayProps> = ({ onClose }) => {
  const [step, setStep] = useState(0);

  const steps = [
    {
      title: "Welcome to the Facility Wiki",
      description: "This portal is designed to help you manage policies, procedures, and forms with ease. This guide will show you how to maintain your knowledge base effectively.",
      icon: <BookOpen className="text-blue-500" size={48} />,
      image:" data:image/png;base64,",
      highlight: "Overview"
    },
    {
      title: "Manual Content Creation",
      description: "Click the 'New Wiki Page' button in the sidebar to manually create a page. You can define the title, category, and select a custom icon for easy navigation.",
      icon: <Plus className="text-blue-600" size={48} />,
      image: "data:image/png;base64,",
      highlight: "Sidebar: Blue Button"
    },
    {
      title: "AI Policy Architect",
      description: "The purple 'AI Policy Architect' button uses Gemini AI to transform your PDF documents into structured wiki pages automatically. Simply upload and review!",
      icon: <Sparkles className="text-purple-600" size={48} />,
      image: "data:image/png;base64,",
      highlight: "Sidebar: Purple Button"
    },
    {
      title: "Admin Mode Toggle",
      description: "Access editing tools by toggling 'Admin Mode' at the bottom of the sidebar. This ensures that only authorized personnel can modify the official documentation.",
      icon: <Settings className="text-slate-600" size={48} />,
      image: "data:image/png;base64,",
      highlight: "Sidebar: Bottom Toggle"
    },
    {
      title: "Editing Content",
      description: "In Admin Mode, hover over any section to see edit and delete icons. You can update text, add images, or attach downloadable forms directly to any page.",
      icon: <Edit2 className="text-blue-400" size={48} />,
      image: "data:image/png;base64,",
      highlight: "Direct Page Interaction"
    },
    {
      title: "You're All Set!",
      description: "You've mastered the basics! Use the centralized knowledge base to keep your department organized and compliant. Click to begin.",
      icon: <CheckCircle2 className="text-green-500" size={48} />,
      image: "https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&q=80&w=1400",
      highlight: "Get Started"
    }
  ];

  const nextStep = () => {
    if (step < steps.length - 1) {
      setStep(step + 1);
    } else {
      onClose();
    }
  };

  useEffect(() => {
    document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = 'auto';
    };
  }, []);

  return (
    <div 
      className="fixed inset-0 z-[200] bg-slate-900/95 backdrop-blur-xl flex items-center justify-center p-8 cursor-pointer select-none"
      onClick={nextStep}
    >
      <div className="absolute top-10 right-10">
        <button 
          onClick={(e) => { e.stopPropagation(); onClose(); }}
          className="p-5 bg-white/10 text-white hover:bg-white/20 rounded-full transition-all shadow-2xl group"
        >
          <X size={32} className="group-hover:rotate-90 transition-transform duration-300" />
        </button>
      </div>

      <div className="max-w-7xl w-full h-[90vh] bg-white rounded-[3rem] shadow-2xl overflow-hidden animate-slideUp pointer-events-none flex flex-col border border-white/20">
        
        {/* Step Image - Larger flex ratio and reduced padding for maximum image size */}
        <div className="flex-[4] bg-slate-50 relative overflow-hidden flex items-center justify-center p-4">
          <img 
            src={steps[step].image} 
            alt={steps[step].title} 
            className="w-full h-full object-contain rounded-2xl transition-all duration-700 hover:scale-105"
            style={{ filter: 'drop-shadow(0 20px 20px rgb(0 0 0 / 0.12))' }}
          />
          
          <div className="absolute top-6 left-6">
             <span className="text-xs font-black text-white uppercase tracking-widest bg-blue-600 px-5 py-2.5 rounded-xl shadow-2xl flex items-center gap-2">
                <span className="w-2 h-2 bg-white rounded-full animate-pulse" />
                Guide Module {step + 1}
             </span>
          </div>
        </div>

        {/* Content Section - Compact padding to give more room to image */}
        <div className="bg-white p-10 pt-6 text-center space-y-6 shrink-0 border-t border-slate-100">
          <div className="flex justify-center -mt-20 relative z-10">
            <div className="bg-white p-6 rounded-[2rem] shadow-2xl border border-slate-100 animate-bounce-subtle ring-4 ring-white">
              {steps[step].icon}
            </div>
          </div>
          
          <div className="space-y-3">
            <span className="text-xs font-bold text-blue-600 uppercase tracking-[0.4em] bg-blue-50 px-3 py-1 rounded-full">
              {steps[step].highlight}
            </span>
            <h2 className="text-4xl font-black text-slate-900 leading-tight tracking-tighter">
              {steps[step].title}
            </h2>
          </div>

          <p className="text-slate-500 text-lg leading-relaxed max-w-3xl mx-auto font-medium">
            {steps[step].description}
          </p>

          <div className="pt-6 flex flex-col items-center gap-6">
             {/* Progress Bar */}
             <div className="flex gap-3">
               {steps.map((_, i) => (
                 <div 
                  key={i} 
                  className={`h-2.5 rounded-full transition-all duration-700 ${i === step ? 'w-20 bg-blue-600 shadow-lg shadow-blue-200' : 'w-3 bg-slate-200'}`} 
                 />
               ))}
             </div>
             
             <div className="flex items-center gap-3 text-sm font-black text-slate-400 uppercase tracking-widest bg-slate-50 px-8 py-3 rounded-[2rem] border border-slate-100 shadow-inner">
               <MousePointer2 size={20} className="animate-pulse text-blue-500" />
               Click anywhere to advance
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TutorialOverlay;
